const APP_VERSION = "0.2.96";

/* v0.2.63: home logo placement + startup splash/crossfade */
const CPTMATE_BRAND_LOGO = "assets/branding/cptmate-horizontal-logo.png";
const CPTMATE_BRAND_ICON = "assets/branding/cptmate-app-icon.png?v=0.2.67";
const CPTMATE_SPLASH_MARK = "data:image/png;base64,";

(function installCPTmateBrandingAndStartup() {
  const installIconLinks = () => {
    const head = document.head;
    if (!head) return;
    if (!document.querySelector('link[data-cptmate-brand-icon="true"]')) {
      const link = document.createElement("link");
      link.rel = "apple-touch-icon";
      link.href = CPTMATE_BRAND_ICON;
      link.dataset.cptmateBrandIcon = "true";
      head.appendChild(link);
    }
    if (!document.querySelector('meta[data-cptmate-brand-theme="true"]')) {
      const meta = document.createElement("meta");
      meta.name = "theme-color";
      meta.content = "#0f5f63";
      meta.dataset.cptmateBrandTheme = "true";
      head.appendChild(meta);
    }
  };

  const installStyle = () => {
    if (document.getElementById("cptmate-branding-style-v063")) return;
    const style = document.createElement("style");
    style.id = "cptmate-branding-style-v063";
    style.textContent = `
      /* Header logo is intentionally not fixed. The official logo lives at the top of Home content. */
      .topbar {
        display: none !important;
      }
      .cptmate-home-logo-wrap {
        width: 100%;
        display: flex;
        justify-content: center;
        align-items: center;
        padding: 6px 0 16px;
      }
      .cptmate-home-logo {
        display: block;
        width: min(300px, 78vw);
        height: auto;
        max-height: 64px;
        object-fit: contain;
        object-position: center;
      }
      .cptmate-startup-splash {
        position: fixed;
        inset: 0;
        z-index: 20000;
        display: flex;
        align-items: center;
        justify-content: center;
        background: #f7fbfb;
        opacity: 1;
        visibility: visible;
        pointer-events: auto;
        transition: opacity .36s ease, visibility 0s linear .36s;
      }
      .cptmate-startup-splash.is-exiting {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
      }
      .cptmate-startup-splash__inner {
        width: min(86vw, 380px);
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 22px;
        transform: translateY(-2vh);
      }
      .cptmate-startup-splash__logo {
        display: block;
        width: min(330px, 78vw);
        height: auto;
        max-height: 100px;
        object-fit: contain;
        animation:none !important;;
      }
      .cptmate-startup-splash__loader {
        width: 34px;
        height: 34px;
        border-radius: 50%;
        border: 3px solid rgba(15,95,99,.14);
        border-top-color: #0f5f63;
        animation: cptmateSplashSpin .85s linear infinite;
      }
      .cptmate-startup-splash__message {
        margin: -8px 0 0;
        color: #718486;
        font-size: 12px;
        font-weight: 700;
        letter-spacing: .08em;
      }
      .screen.cptmate-home-ready {
        animation: cptmateHomeCrossfade .36s ease both;
      }
      @keyframes cptmateSplashLogoPulse {
        0%, 100% { opacity: .92; transform: scale(.985); }
        50% { opacity: 1; transform: scale(1); }
      }
      @keyframes cptmateSplashSpin { to { transform: rotate(360deg); } }
      @keyframes cptmateHomeCrossfade {
        from { opacity: 0; transform: translateY(4px); }
        to { opacity: 1; transform: translateY(0); }
      }
      @media (max-width: 430px) {
        .cptmate-home-logo {
          width: min(280px, 78vw);
          max-height: 58px;
        }
        .cptmate-startup-splash__logo {
          width: min(280px, 72vw);
        }
      }
      @media (prefers-reduced-motion: reduce) {
        .cptmate-startup-splash,
        .screen.cptmate-home-ready { transition: none !important; animation: none !important; }
        .cptmate-startup-splash__logo,
        .cptmate-startup-splash__loader { animation: none !important; }
      }
    `;
    document.head.appendChild(style);
  };

  const ensureSplash = () => {
    let splash = document.getElementById("cptmate-startup-splash");
    if (splash) return splash;
    splash = document.createElement("div");
    splash.id = "cptmate-startup-splash";
    splash.className = "cptmate-startup-splash";
    splash.setAttribute("role", "status");
    splash.setAttribute("aria-live", "polite");
    splash.innerHTML = `
      <div class="cptmate-startup-splash__inner">
        <img class="cptmate-startup-splash__logo" src="${CPTMATE_SPLASH_MARK}" alt="CPTmate" decoding="async" />
        <div class="cptmate-startup-splash__loader" aria-hidden="true"></div>
        <p class="cptmate-startup-splash__message">起動しています…</p>
      </div>
    `;
    document.body.appendChild(splash);
    return splash;
  };

  installIconLinks();
  installStyle();
  const splash = ensureSplash();
  window.__cptmateSplashStartedAt = performance.now();
  window.__cptmateFinishSplash = () => {
    if (window.__cptmateSplashFinished) return;
    window.__cptmateSplashFinished = true;
    const elapsed = performance.now() - window.__cptmateSplashStartedAt;
    const wait = Math.max(0, 1500 - elapsed);
    setTimeout(() => {
      const screen = document.getElementById("screen");
      if (screen) screen.classList.add("cptmate-home-ready");
      splash.classList.add("is-exiting");
      setTimeout(() => splash.remove(), 420);
    }, wait);
  };

  // v0.2.75: 起動処理の例外で終了関数が呼ばれなくても、
  // スプラッシュが永久に残らないよう安全弁を設置する。
  window.setTimeout(() => {
    const screen = document.getElementById("screen");
    if (screen) screen.classList.add("cptmate-home-ready");
    const currentSplash = document.getElementById("cptmate-startup-splash");
    if (currentSplash) {
      currentSplash.classList.add("is-exiting");
      window.setTimeout(() => currentSplash.remove(), 420);
    }
  }, 2300);
})();

/* v0.2.64: bottom navigation — restore approved 4-item layout */
(function installCPTmateBottomNavFix() {
  const apply = () => {
    const nav = document.querySelector(".bottom-nav");
    if (!nav) return;

    const buttons = Array.from(nav.querySelectorAll(".nav-btn"));
    const byKey = Object.fromEntries(buttons.map(btn => [btn.dataset.nav, btn]));

    // Approved order: Home / Review / Favorites / Settings.
    const navOrder = ["home", "review", "favorites", "settings"];

    // Remove the legacy stats button from layout entirely.
    const statsButton = byKey.stats;
    if (statsButton) statsButton.remove();

    navOrder.forEach(key => {
      const btn = byKey[key];
      if (btn) nav.appendChild(btn);
    });

    nav.style.setProperty("position", "fixed", "important");
    nav.style.setProperty("left", "0", "important");
    nav.style.setProperty("right", "0", "important");
    nav.style.setProperty("bottom", "0", "important");
    nav.style.setProperty("width", "100%", "important");
    nav.style.setProperty("max-width", "none", "important");
    nav.style.setProperty("height", "auto", "important");
    nav.style.setProperty("margin", "0", "important");
    nav.style.setProperty("transform", "none", "important");
    nav.style.setProperty("z-index", "9999", "important");
    nav.style.setProperty("box-sizing", "border-box", "important");
    nav.style.setProperty("display", "grid", "important");
    nav.style.setProperty("grid-template-columns", "repeat(4, minmax(0, 1fr))", "important");
    nav.style.setProperty("align-items", "stretch", "important");
    nav.style.setProperty("padding", "0 0 env(safe-area-inset-bottom)", "important");

    navOrder.forEach(key => {
      const btn = byKey[key];
      if (!btn) return;

      btn.style.setProperty("display", "flex", "important");
      btn.style.setProperty("flex-direction", "column", "important");
      btn.style.setProperty("align-items", "center", "important");
      btn.style.setProperty("justify-content", "center", "important");
      btn.style.setProperty("width", "100%", "important");
      btn.style.setProperty("min-width", "0", "important");
      btn.style.setProperty("height", "68px", "important");
      btn.style.setProperty("min-height", "68px", "important");
      btn.style.setProperty("padding", "7px 2px 6px", "important");
      btn.style.setProperty("margin", "0", "important");
      btn.style.setProperty("gap", "3px", "important");
      btn.style.setProperty("box-sizing", "border-box", "important");
      btn.style.setProperty("flex", "none", "important");
      btn.style.setProperty("text-align", "center", "important");

      const icon = btn.querySelector("span");
      const label = btn.querySelector("small");

      if (icon) {
        icon.style.setProperty("display", "block", "important");
        icon.style.setProperty("font-size", "22px", "important");
        icon.style.setProperty("line-height", "1", "important");
        icon.style.setProperty("height", "24px", "important");
      }
      if (label) {
        label.style.setProperty("display", "block", "important");
        label.style.setProperty("font-size", "10px", "important");
        label.style.setProperty("line-height", "1.2", "important");
        label.style.setProperty("white-space", "nowrap", "important");
      }
    });

    document.body.style.setProperty(
      "padding-bottom",
      "calc(68px + env(safe-area-inset-bottom))",
      "important"
    );
  };

  apply();
  requestAnimationFrame(apply);
  setTimeout(apply, 100);
  setTimeout(apply, 500);
})();
